head.script:
scwin.checkVal1 = function() {
	return typeof (document.getElementById('w1_input1') || document.getElementById('mf_w1_input1')) == 'object';
};

scwin.checkVal2 = function() {
	return (document.getElementById('w1_input1') || document.getElementById('mf_w1_input1')).getAttribute('imemode') == undefined;
};

scwin.checkVal3 = function() {
	return ((j) => j.length ? j : $('#mf_w1'))($('#w1')).html() == undefined;
};

// wframe 의 scope scwin 전역 객체(<프레임 id>_scwin) 타입
scwin.getScwinType = function(frameId) {
	return typeof window[$p.id + frameId + "_scwin"];
};
